-- PaperGo schema. Pre-release: edit this file in place; do not add migrations
-- (see AGENTS.md). Ent models the tables and indexes; the FTS tables and the
-- integrity, projection and permission-scope triggers are SQLite-specific and
-- are not generated by Ent.

-- Tables
CREATE TABLE `audit_events` (`id` text NOT NULL, `created_at` datetime NOT NULL, `workspace_id` text NOT NULL, `resource_id` text NOT NULL, `subject` text NOT NULL, `action` text NOT NULL, `details` json NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `blobs` (`id` text NOT NULL, `created_at` datetime NOT NULL, `version` integer NOT NULL, `object_key` text NOT NULL, `filename` text NOT NULL, `content_type` text NOT NULL, `size` integer NOT NULL, `sha256` text NOT NULL, `item_id` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `blobs_resources_blobs` FOREIGN KEY (`item_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `field_definitions` (`id` text NOT NULL, `created_at` datetime NOT NULL, `key` text NOT NULL, `label` text NOT NULL, `type` text NOT NULL, `required` bool NOT NULL DEFAULT (false), `choices` json NOT NULL, `container_id` text NOT NULL, indexed BOOLEAN NOT NULL DEFAULT 0, scale INTEGER NOT NULL DEFAULT 0, options JSON NOT NULL DEFAULT '{}' CHECK(json_valid(options) AND json_type(options)='object'), PRIMARY KEY (`id`), CONSTRAINT `field_definitions_resources_definitions` FOREIGN KEY (`container_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `grants` (`id` text NOT NULL, `created_at` datetime NOT NULL, `subject` text NOT NULL, `action` text NOT NULL, `effect` text NOT NULL, `resource_id` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `grants_resources_grants` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `publications` (`id` text NOT NULL, `created_at` datetime NOT NULL, `version` integer NOT NULL, `published_by` text NOT NULL, `snapshot` json NOT NULL, `item_id` text NOT NULL, action TEXT NOT NULL DEFAULT 'publish', revision_id TEXT REFERENCES item_revisions(id), PRIMARY KEY (`id`), CONSTRAINT `publications_resources_publications` FOREIGN KEY (`item_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `relationships` (`id` text NOT NULL, `created_at` datetime NOT NULL, `workspace_id` text NOT NULL, `name` text NOT NULL, `metadata` json NOT NULL, `source_id` text NOT NULL, `target_id` text NOT NULL, type_id TEXT NOT NULL REFERENCES relationship_types(id), directed BOOLEAN NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), PRIMARY KEY (`id`), CONSTRAINT `relationships_resources_outgoing` FOREIGN KEY (`source_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION, CONSTRAINT `relationships_resources_incoming` FOREIGN KEY (`target_id`) REFERENCES `resources` (`id`) ON DELETE NO ACTION);
CREATE TABLE `resources` (`id` text NOT NULL, `created_at` datetime NOT NULL, `workspace_id` text NOT NULL, `kind` text NOT NULL, `name` text NOT NULL, `tags` json NOT NULL, `values` json NOT NULL, `inherit_permissions` bool NOT NULL DEFAULT (true), `version` integer NOT NULL DEFAULT (1), `updated_at` datetime NOT NULL, `scope_id` text NULL, `parent_id` text NULL, `container_id` text NULL, head_revision_id TEXT REFERENCES item_revisions(id), published_revision_id TEXT REFERENCES item_revisions(id), schema_head_id TEXT REFERENCES schema_revisions(id), next_revision_number INTEGER NOT NULL DEFAULT 1, publishing_enabled BOOLEAN NOT NULL DEFAULT 0, webdav_enabled BOOLEAN NOT NULL DEFAULT 0, name_key TEXT NULL, deleted_at DATETIME NULL, created_by TEXT NOT NULL DEFAULT '', updated_by TEXT NOT NULL DEFAULT '', content_type_id TEXT NULL, template_keys JSON NOT NULL DEFAULT '[]' CHECK(json_valid(template_keys) AND json_type(template_keys)='array' AND json_array_length(template_keys)<=100 AND (kind IN ('list','library') OR json_array_length(template_keys)=0)), PRIMARY KEY (`id`), CONSTRAINT `resources_resources_children` FOREIGN KEY (`parent_id`) REFERENCES `resources` (`id`) ON DELETE SET NULL, CONSTRAINT `resources_resources_contained_items` FOREIGN KEY (`container_id`) REFERENCES `resources` (`id`) ON DELETE SET NULL, CHECK(deleted_at IS NULL OR name_key IS NULL), CHECK((kind='item')=(content_type_id IS NOT NULL)), FOREIGN KEY(container_id,content_type_id) REFERENCES content_types(container_id,id));
CREATE TABLE resource_tags (
  resource_id TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE,
  tag TEXT NOT NULL,
  PRIMARY KEY (tag,resource_id)
) WITHOUT ROWID;
CREATE TABLE schema_revisions (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, container_id TEXT NOT NULL REFERENCES resources(id),
 revision_number INTEGER NOT NULL CHECK(revision_number>0), definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'), created_by TEXT NOT NULL
);
CREATE TABLE content_types (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 container_id TEXT NOT NULL REFERENCES resources(id), key TEXT NOT NULL, name TEXT NOT NULL,
 field_keys JSON NOT NULL CHECK(json_valid(field_keys) AND json_type(field_keys)='array'),
 rules JSON NOT NULL CHECK(json_valid(rules) AND json_type(rules)='array'),
 is_default BOOLEAN NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE business_keys (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 container_id TEXT NOT NULL REFERENCES resources(id), item_id TEXT NOT NULL REFERENCES resources(id),
 field_key TEXT NOT NULL, value TEXT NOT NULL
);
CREATE TABLE item_revisions (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL,
 item_id TEXT NOT NULL REFERENCES resources(id), container_id TEXT NOT NULL REFERENCES resources(id),
 schema_revision_id TEXT NOT NULL, content_type_id TEXT NOT NULL, revision_number INTEGER NOT NULL CHECK(revision_number>0),
 name TEXT NOT NULL, tags JSON NOT NULL CHECK(json_valid(tags) AND json_type(tags)='array'), payload JSON NOT NULL CHECK(json_valid(payload) AND json_type(payload)='object'),
 created_by TEXT NOT NULL, blob_id TEXT REFERENCES blobs(id),
 FOREIGN KEY(container_id,schema_revision_id) REFERENCES schema_revisions(container_id,id),
 FOREIGN KEY(container_id,content_type_id) REFERENCES content_types(container_id,id)
);
CREATE TABLE item_surfaces (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, item_id TEXT NOT NULL REFERENCES resources(id),
 container_id TEXT NOT NULL REFERENCES resources(id), workspace_id TEXT NOT NULL,
 surface TEXT NOT NULL CHECK(surface IN ('head','published')), revision_id TEXT NOT NULL,
 name TEXT NOT NULL, tags JSON NOT NULL CHECK(json_valid(tags) AND json_type(tags)='array'), payload JSON NOT NULL CHECK(json_valid(payload) AND json_type(payload)='object'),
 item_created_at TEXT NOT NULL, item_created_by TEXT NOT NULL, modified_at TEXT NOT NULL, modified_by TEXT NOT NULL,
 FOREIGN KEY(item_id,revision_id) REFERENCES item_revisions(item_id,id)
);
CREATE TABLE item_surface_tags(surface_id TEXT NOT NULL REFERENCES item_surfaces(id) ON DELETE CASCADE,tag TEXT NOT NULL,PRIMARY KEY(tag,surface_id)) WITHOUT ROWID;
CREATE TABLE "field_values" (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, surface_id TEXT NOT NULL REFERENCES item_surfaces(id),
 container_id TEXT NOT NULL, item_id TEXT NOT NULL, surface TEXT NOT NULL, field_key TEXT NOT NULL, field_type TEXT NOT NULL,
 scale INTEGER NOT NULL DEFAULT 0, ordinal INTEGER NOT NULL DEFAULT 0 CHECK(ordinal>=0 AND ordinal<100),
 value_text TEXT, value_integer INTEGER, value_number REAL, value_boolean BOOLEAN,
 CHECK((value_text IS NOT NULL)+(value_integer IS NOT NULL)+(value_number IS NOT NULL)+(value_boolean IS NOT NULL)=1),
 CHECK((field_type IN ('text','note','email','url','date','lookup','term','choice','datetime') AND value_text IS NOT NULL)
 OR (field_type IN ('integer','decimal') AND value_integer IS NOT NULL)
 OR (field_type='number' AND value_number IS NOT NULL)
 OR (field_type='boolean' AND value_boolean IS NOT NULL AND value_boolean IN (0,1))),
 CHECK(scale BETWEEN 0 AND 9 AND (field_type='decimal' OR scale=0)),
 CHECK(value_integer IS NULL OR typeof(value_integer)='integer'),
 CHECK(value_number IS NULL OR typeof(value_number) IN ('real','integer'))
);
CREATE TABLE schema_templates (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,workspace_id TEXT NOT NULL REFERENCES resources(id),
 key TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'),
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE term_sets (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,workspace_id TEXT NOT NULL REFERENCES resources(id),
 key TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE terms (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,term_set_id TEXT NOT NULL REFERENCES term_sets(id),
 parent_id TEXT REFERENCES terms(id),name TEXT NOT NULL,normalized_name TEXT NOT NULL,
 labels JSON NOT NULL CHECK(json_valid(labels) AND json_type(labels)='object'),synonyms JSON NOT NULL CHECK(json_valid(synonyms) AND json_type(synonyms)='array'),
 deprecated BOOLEAN NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE list_views (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,container_id TEXT NOT NULL REFERENCES resources(id),
 name TEXT NOT NULL,columns JSON NOT NULL CHECK(json_valid(columns) AND json_type(columns)='array'),
 query JSON NOT NULL CHECK(json_valid(query) AND json_type(query)='object'),layout TEXT NOT NULL DEFAULT 'table' CHECK(layout IN ('table','board','calendar','gallery')),
 is_default BOOLEAN NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0)
);
CREATE TABLE webdav_credentials (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,subject TEXT NOT NULL,label TEXT NOT NULL,
 secret_hash TEXT NOT NULL CHECK(length(secret_hash)=64),expires_at DATETIME
);
CREATE TABLE smart_folders (
 id TEXT PRIMARY KEY NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL,
 workspace_id TEXT REFERENCES resources(id), owner_id TEXT,
 name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
 definition JSON NOT NULL CHECK(json_valid(definition) AND json_type(definition)='object'),
 created_by TEXT NOT NULL, updated_by TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(workspace_id IS NOT NULL OR owner_id IS NOT NULL), CHECK(owner_id IS NULL OR length(owner_id)>0)
);
CREATE TABLE relationship_types (
 id TEXT PRIMARY KEY NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,workspace_id TEXT NOT NULL REFERENCES resources(id),
 key TEXT NOT NULL,label TEXT NOT NULL,inverse_label TEXT NOT NULL DEFAULT '',directed BOOLEAN NOT NULL DEFAULT 1,
 max_incoming INTEGER CHECK(max_incoming BETWEEN 1 AND 1000),max_outgoing INTEGER CHECK(max_outgoing BETWEEN 1 AND 1000),
 attributes JSON NOT NULL CHECK(json_valid(attributes) AND json_type(attributes)='object'),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 CHECK(directed OR (inverse_label='' AND max_incoming IS NULL AND max_outgoing IS NULL))
);

-- Full-text search over resources and item surfaces (external content)
CREATE VIRTUAL TABLE resource_search USING fts5(
  id UNINDEXED, name, tags, "values",
  content='resources', content_rowid='rowid', tokenize='unicode61'
);
CREATE VIRTUAL TABLE item_surface_search USING fts5(id UNINDEXED,name,tags,payload,content='item_surfaces',content_rowid='rowid',tokenize='unicode61');

